final class SideDrawer {
 static boolean close(MainActivity a){if(a.mainFrame==null)return false;View old=a.mainFrame.findViewWithTag("audivo-drawer");if(old==null)return false;a.mainFrame.removeView(old);return true;}
 static void show(MainActivity a){
  if(a.mainFrame==null)return;close(a);FrameLayout overlay=new FrameLayout(a);overlay.setTag("audivo-drawer");View shade=new View(a);shade.setBackgroundColor(0x77000000);shade.setOnClickListener(v->close(a));overlay.addView(shade,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout panel=a.column();panel.setBackgroundColor(AppTheme.surface);panel.setElevation(a.dp(12));int width=Math.min(a.dp(280),a.getResources().getDisplayMetrics().widthPixels-a.dp(56));overlay.addView(panel,new FrameLayout.LayoutParams(width,-1,Gravity.START));LinearLayout header=a.row();header.setPadding(a.dp(20),a.dp(14),a.dp(12),a.dp(14));TextView title=a.text("Clavis",23,MainActivity.INK,true);title.setTypeface(a.serif,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));header.addView(UiStyle.icon(a,R.drawable.ic_arrow_back,"Close navigation",()->close(a),34));panel.addView(header);View rule=new View(a);rule.setBackgroundColor(AppTheme.line);panel.addView(rule,new LinearLayout.LayoutParams(-1,a.dp(1)));a.space(panel,6);TextView motto=a.text("READ · LISTEN · DISCOVER",10,AppTheme.muted,false);motto.setLetterSpacing(.12f);motto.setPadding(a.dp(20),0,a.dp(12),a.dp(14));panel.addView(motto);ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);LinearLayout links=a.column();scroll.addView(links);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  entry(a,links,"Home",R.drawable.ic_home,()->a.home());entry(a,links,"Ebooks",R.drawable.ic_book,()->a.library("EPUB"));entry(a,links,"PDF Books",R.drawable.ic_pdf,()->a.library("PDF"));entry(a,links,"Audio Books",R.drawable.ic_listen_audio,()->a.library("Audio"));entry(a,links,"Articles",R.drawable.ic_journal,()->a.library("Journals"));entry(a,links,"Journalling",R.drawable.ic_pen,()->a.library("Journalling"));a.space(links,16);entry(a,links,"Browse audiobooks",R.drawable.ic_search,()->a.startActivity(new android.content.Intent(a,AudiobookBrowserActivity.class)));entry(a,links,"Browse ebooks",R.drawable.ic_book,()->a.startActivity(new android.content.Intent(a,AudiobookBrowserActivity.class).putExtra("ebook",true)));entry(a,links,"Listen",R.drawable.ic_listen_audio,()->Listen.resume(a));entry(a,links,"Downloads",R.drawable.ic_listen_audio,()->a.startActivity(new android.content.Intent(a,DownloadsActivity.class)));entry(a,links,"Files",R.drawable.ic_book,()->SharedDownloads.open(a));entry(a,links,"Settings",R.drawable.ic_cursor,()->settings(a));
  a.mainFrame.addView(overlay,new FrameLayout.LayoutParams(-1,-1));panel.setTranslationX(-width);panel.animate().translationX(0).setDuration(180).start();
 }
 static void entry(MainActivity a,LinearLayout parent,String name,int resource,Runnable action){LinearLayout row=a.row();row.setPadding(a.dp(12),a.dp(3),a.dp(12),a.dp(3));android.util.TypedValue selectable=new android.util.TypedValue();a.getTheme().resolveAttribute(android.R.attr.selectableItemBackground,selectable,true);row.setBackgroundResource(selectable.resourceId);row.addView(UiStyle.icon(a,resource,name,()->{close(a);action.run();},34));TextView label=a.text(name,15,MainActivity.INK,true);label.setPadding(a.dp(12),0,0,0);row.addView(label,new LinearLayout.LayoutParams(0,a.dp(44),1));label.setGravity(Gravity.CENTER_VERTICAL);row.setOnClickListener(v->{close(a);action.run();});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(a.dp(10),a.dp(3),a.dp(10),a.dp(3));parent.addView(row,rp);}
 static void settings(MainActivity a){new AppDialog.Builder(a).setTitle("Settings").setItems(new String[]{"Audiobook website","Ebook website","Appearance","Downloads and storage"},(d,n)->{if(n==0)BrowserSettings.show(a);else if(n==1)BrowserSettings.show(a,true);else if(n==2)appearance(a);else DownloadSettings.show(a);}).setNegativeButton("Close",null).show();}
 static void appearance(MainActivity a){new AppDialog.Builder(a).setTitle("Appearance").setSingleChoiceItems(new String[]{"Light","Dark"},AppTheme.isDark(a)?1:0,(d,n)->{AppTheme.setDark(a,n==1);d.dismiss();a.recreate();}).setNegativeButton("Close",null).show();}
}
